        row.append("td").text(d.sector);
        row.append("td").text(formatMC(d.marketCap));
    });

    function highlight(selectedData) {
        // Highlight circle
        node.classed("highlighted", d => d === selectedData);

        // Highlight table row
        tableBody.selectAll("tr")
            .classed("highlighted", d => d === selectedData);

        // Scroll table to row
